import{z as l,x as s,o as t,c as C,q as B,j as n,D as e,d as a,s as i,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"对手方信用管理","description":"","frontmatter":{"title":"对手方信用管理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-counterparty-credit.md","filePath":"quant/ot-counterparty-credit.md","lastUpdated":1791063341000}'),p={name:"quant/ot-counterparty-credit.md"};function d(D,E,u,h,m,c){const r=s("Mermaid");return t(),C("div",null,[E[2]||(E[2]=B('<h1 id="对手方信用管理" tabindex="-1">对手方信用管理 <a class="header-anchor" href="#对手方信用管理" aria-label="Permalink to &quot;对手方信用管理&quot;">​</a></h1><div class="epigraph"><p>对手方风险是三件套的乘积：违约概率、未来暴露、违约后损失；合同决定暴露怎么算，信用决定这个暴露值多少钱。</p><footer>—— 据 Gregory, The xVA Challenge；Canabarro and Duffie, 2003 的口径整理</footer></div><p><a href="/quant/ot-isda-documentation">上一课</a>把净额集与 CSA 的法律构造搭好。本课把信用定价层加上：净额集决定暴露怎么聚合，违约概率与回收决定这个暴露折多少钱。结构化产品有两条信用线：发行台对对手方的暴露（对冲腿、互惠头寸），与投资者对发行人的暴露（票据本身是无担保负债）。两条线的工法不同，后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一条线是发行台的标准问题：净额集上的 EE 剖面乘上违约概率。结构化产品让它变难：障碍负债的暴露在敲入情景跳变——EE 剖面在观察时钟附近不连续，网格对不准时钟就漏掉尖峰；期限以年计，尾部违约概率的误差被长贴现放大。第二条线更基本：买入雪球或 FCN 的投资者持有的是发行人的无担保债权，产品的对冲再干净，发行人违约时票据按违约清偿处置。2008 年雷曼兄弟破产时，香港市场以「迷你债券」名义发行的零售结构化票据余额以百亿港元计，分销行最终向多数持有人安排回购——「结构安全」与「发行安全」是两件事，这是本课钉住的第一判据。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分解式是共同的骨架：</p> \\[\\mathrm{CVA}=\\mathrm{LGD}\\cdot\\sum_i \\mathrm{DF}(t_i)\\,\\mathrm{EE}(t_i)\\,\\Delta Q_i . \\]<p>发行台侧按<a href="/quant/cva-exposure-profile">暴露剖面</a>的口径构造 EE：净额集为聚合单位、CSA 参数进剖面、网格对准支付日与观察时钟；\\(\\Delta Q\\) 沿 CDS 自举，无 CDS 的市场按映射计，映射与剖面分列敏感度。缓释按合同参数走：阈值、独立金额、抵押折扣改写 EE 的水平与形状；预付与限额改写增量业务的暴露上限，限额体系沿<a href="/quant/rk-counterparty-system">对手方风险体系</a>挂情景限额而不是单笔敞口。</p><p><span class="marginnote">术语翻译：CVA（信用估值调整）就是把「对手可能赖账」折成价格——每一期你暴露给对方的金额，乘上对方当期违约概率、再乘违约后拿不回的比例，贴现加总。它不是手续费，是这笔交易公允价值里本该扣掉的一块。</span></p><p><span class="marginnote">数字实例：某对手 5 年累计违约概率 10%，平均暴露 EE 2000 万，违约后回收 40%（即 LGD=60%）。CVA 约 \\(2000\\text{万}\\times10\\%\\times60\\%=120\\) 万——谈判桌上，这 120 万应体现为更宽的报价、更高的抵押，或干脆换对手。</span></p><p><span class="marginnote">错向不是乘一个大于 1 的系数：把违约概率做成市场因子的函数，让暴露与违约在联合分布里同向放大，才是能进引擎、能对账的做法。<a href="/quant/rates-credit-hybrid">利率-信用混合定价</a>立的判据在 2020 年 3 月被<a href="/quant/rc-case-map">利率信用收束课</a>的案例兑现——卖出期权给低信用对手，正是暴露与 PD 同涨的结构。</span></p><p>投资者侧的缓释更薄：票据持有人没有 CSA 可签，能做的是额度、期限与发行人分散，以及把发行人信用价差折进票息要求——同一结构，两家发行人的公允票息不同，差额就是市场对发行人信用的定价。</p><p><span class="marginnote">常见误区：买雪球或 FCN 时只比票息高低、不问发行人。同一结构 A 家给 5%、B 家给 5.8%，多出的 0.8% 多半不是让利，而是市场给 B 更低信用开的补偿——票息差是发行人信用价的镜子，不是免费的午餐。</span></p>',14)),(t(),n(o,null,{default:e(()=>[i(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E5%87%80%E9%A2%9D%E9%9B%86%20EE%20%E5%89%96%E9%9D%A2%EF%BC%9A%E5%90%AB%20CSA%20%E4%B8%8E%E6%97%B6%E9%92%9F%22%5D%20--%3E%20CVA%5B%22CVA%EF%BC%9AEE%20%E4%B9%98%20DF%20%E4%B9%98%20%CE%94Q%20%E4%B9%98%20LGD%22%5D%0A%20%20PD%5B%22%E8%BF%9D%E7%BA%A6%E6%A6%82%E7%8E%87%EF%BC%9ACDS%20%E8%87%AA%E4%B8%BE%E6%88%96%E6%98%A0%E5%B0%84%22%5D%20--%3E%20CVA%0A%20%20WRC%5B%22%E9%94%99%E5%90%91%EF%BC%9APD%20%E4%BE%9D%E8%B5%96%E5%B8%82%E5%9C%BA%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20PD%0A%20%20CVA%20--%3E%20HL%5B%22%E9%99%90%E9%A2%9D%E4%B8%8E%E7%BC%93%E9%87%8A%EF%BC%9A%E9%98%88%E5%80%BC%E3%80%81%E6%8A%B5%E6%8A%BC%E3%80%81%E9%A2%84%E4%BB%98%22%5D%0A%20%20ISS%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E4%BE%A7%EF%BC%9A%E5%8F%91%E8%A1%8C%E4%BA%BA%E6%97%A0%E6%8B%85%E4%BF%9D%E8%B4%9F%E5%80%BA%22%5D%20--%3E%20SP%5B%22%E4%BF%A1%E7%94%A8%E4%BB%B7%E5%B7%AE%E6%8A%98%E8%BF%9B%E7%A5%A8%E6%81%AF%E8%A6%81%E6%B1%82%22%5D%0A%20%20ISS%20--%3E%20DIV%5B%22%E9%A2%9D%E5%BA%A6%E4%B8%8E%E5%8F%91%E8%A1%8C%E4%BA%BA%E5%88%86%E6%95%A3%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("两条线在机制上汇于一点：信用成本必须回到价格。"),A("a",{href:"/quant/ot-issuer-hedging"},"发行方视角"),a("的发行价差里，\\(c^{*}\\) 的信用成本项就是发行台自己被要求的 CVA/DVA；投资者票息里被压掉的部分，是发行人信用价差的镜像。障碍产品 EE 的跳变使这条定价链对网格与敏感度格外挑剔：敲入情景把负债推向投资者，发行台侧的 EE 与 DVA 同时改写，静止单点暴露看不到。不这么做会错在哪：按「产品已对冲」给发行人信用零权重，等于把 2008 年的结构性错配原样重建。")],-1)),(t(),n(o,null,{default:e(()=>[i(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%91%E8%A1%8C%E5%8F%B0%EF%BC%9A%E5%AF%B9%E5%AF%B9%E6%89%8B%E6%96%B9%E6%9A%B4%E9%9C%B2%E7%9A%84CVA%22%5D%20--%3E%20P%5B%22%E5%8F%91%E8%A1%8C%E4%BB%B7%E5%B7%AE%E4%B8%AD%E7%9A%84%E4%BF%A1%E7%94%A8%E6%88%90%E6%9C%AC%E9%A1%B9%22%5D%0A%20%20B%5B%22%E6%8A%95%E8%B5%84%E8%80%85%EF%BC%9A%E5%AF%B9%E5%8F%91%E8%A1%8C%E4%BA%BA%E7%9A%84%E6%97%A0%E6%8B%85%E4%BF%9D%E5%80%BA%E6%9D%83%22%5D%20--%3E%20Q%5B%22%E7%A5%A8%E6%81%AF%E6%8A%98%E4%BB%B7%20%3D%20%E5%8F%91%E8%A1%8C%E4%BA%BA%E4%BF%A1%E7%94%A8%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P%20--%3E%20M%5B%22%E5%90%8C%E4%B8%80%E7%BB%93%E6%9E%84%E7%9A%84%E5%85%AC%E5%85%81%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20Q%20--%3E%20M%0A%20%20A%20--%3E%20K%7B%22%E9%9A%9C%E7%A2%8D%E6%95%B2%E5%85%A5%E6%83%85%E6%99%AF%3F%22%7D%0A%20%20K%20--%3E%7C%22%E6%98%AF%22%7C%20J%5B%22EE%E4%B8%8EDVA%E5%90%8C%E6%97%B6%E8%B7%B3%E5%8F%98%22%5D%0A%20%20K%20--%3E%7C%22%E5%90%A6%22%7C%20S%5B%22EE%E6%B2%BF%E6%97%B6%E9%97%B4%E5%B9%B3%E6%BB%91%22%5D%0A%20%20J%20--%3E%20M%0A%20%20S%20--%3E%20M%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CVA 的对冲（CDS 对 \\(\\Delta Q\\)、市场因子对 EE 的导数）沿<a href="/quant/cva-exposure-profile">暴露剖面</a>课，不再展开；监管资本侧的 EEPE 与 SA-CCR 沿<a href="/quant/rc-regcap-pricing">监管资本下的定价</a>。中央清算把双边暴露换成对 CCP 的暴露加违约基金，对象改变，口径沿 <a href="/quant/ccp-clearing">CCP 清算</a>。发行人信用进产品条款的方式（担保、抵押、破产隔离的 SPV 结构）只点名不展开，那是产品设计的另一个课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对手方信用是三件套：PD、EE、LGD；合同定暴露算法，信用定价格。</li><li>结构化产品的 EE 在敲入情景跳变，网格必须对准观察时钟与支付日。</li><li>错向进联合分布不进系数；卖出期权给低信用对手是同向放大的典型结构。</li><li>投资者侧的发行人信用没有 CSA 可缓释：额度、分散、价差折进票息是全部工具。</li><li>出处：Gregory, <em>The xVA Challenge</em>；Canabarro and Duffie, 2003；口径沿 <a href="/quant/cva-exposure-profile">CVA 暴露剖面</a>与<a href="/quant/rk-counterparty-system">对手方风险体系</a>。</li></ul>',4))])}const _=l(p,[["render",d]]);export{F as __pageData,_ as default};
